#!/usr/bin/env python3
"""Make scoped approvals for four successful consumers, preserving fifth diagnostic."""
from pathlib import Path
import json,hashlib
from datetime import datetime,timezone
BASE=Path(__file__).resolve().parent;REPO=BASE.parents[5]
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
lock=json.loads((BASE/'source-lock.json').read_text());p=BASE/'run-attempt-1/result.json';result=json.loads(p.read_text())
assert not result['passed']
assert [(c['source'],c['exit_code']) for c in result['commands'] if c['exit_code']]==[('Independent_svd_memory_Consumer.lean',1)]
assert result['driver_sha256']==sha(BASE/'replay.py')
assert result['lean_sha256']=='1b370cfcbf44e80d1b004ab1b1ab9a4c73951f9f7c242140bcff9bc577576554'
assert all(x['passed'] for field in ['dependencies_before','dependencies_after','original25_before','original25_after'] for x in result[field])
assert all(result['source_unchanged_after'].values()) and all(result['author_locks_unchanged_after'].values())
notes={
'recursive_tensor':{'review':'Actual tensor entries, unfoldings, cut ranks, contractions, lifts and merge maps are transported by explicit linear equivalences. Completion requires actual SVD and child Completion responses; its constructors contain no assumed correctness guarantee. The ordinary comparator bound and attained-sInf-optimum estimate hold for every response. The projected estimate allows every supplied orthonormal first frame; exact zero follows from the actual squared error.','limits':'Ordinary non-strict bound and projected comparison only. Strict improvement, finite RAM realization and polynomial total cost are outside this block.','inventory_note':'All125 authored declarations, including the two leading-indentation theorems prefix_join_coordinate and suffix_join_coordinate, are explicitly checked. Namespace tracking is unchanged.'},
'svd_tie':{'review':'The sorted singular values define the entire consecutive above/tied threshold block. Finite cyclic selections have the stated exact counts and actual rank/orthonormal frames. Every selected projector has the actual first tail error. Equality residuals yield the exact take/tied mean identity, full-tie annihilation, and strict residual contraction for some candidate when positive. Arbitrary orthonormal frames implement their actual QQᵀ span projector.','limits':'Singular-direction conclusions range over Fin(min m l); positive threshold directions are covered. This is the matrix tie construction, with no complete tensor algorithm, RAM implementation or global complexity claim.'},
'scalar_programs':{'review':'Scalar instruction execution is related to actual legal traces and charged cost. The fixed copy program copies each actual source cell and preserves outside memory under the literal nonoverlap hypotheses, with halt/cost at most6N+2. The fixed header decoder uses only castNat, equalReal, increment and halt; every legal trace from its stated loop state returns the supplied natural at3n+3 with that cost bound and unchanged memory.','limits':'The decoder assumes real register0 already contains the cast natural header. Loading an InputMemory header, assembling callers and bounding an entire algorithm remain separate. It makes no termination claim for arbitrary nonnatural real headers.'},
'radix_interface':{'review':'The explicit last-index-fastest radix equivalence agrees with the immutable original Offset and Decode in both directions. The actual InputMemory tensor cell is recovered at its literal dense address. Any supplied legal radix SVD is transported by a right-column permutation to the existing dense-first Completion interface, retaining exactly U and sigma.','limits':'This supplies exact indexing and transport of arbitrary legal replies. It does not implement the whole recursive RAM algorithm or establish its total cost.'}}
receipts=[]
for b in lock['blocks']:
 key=b['key']
 if key not in notes:continue
 r=result['blocks'][key];assert r['passed']
 for v in b['records']:assert sha(REPO/v['path'])==v['sha256']
 consumer=r['consumer'];assert sha(BASE/'run-attempt-1'/consumer['log'])==consumer['log_sha256']
 record={'approval':'APPROVED_FROZEN_SUPPORT_ONLY','passed':True,'execution_started_utc':result['started_utc'],'execution_finished_utc':result['finished_utc'],'review_recorded_utc':datetime.now(timezone.utc).isoformat(),'reviewer':'/root/recover_verification','proof_source_authorship':[],'block':key,'author':b['author'],'source_review':notes[key],'author_source_lock':{'path':b['author_lock_path'],'sha256':b['author_lock_sha256']},'independent_union_source_lock_sha256':sha(BASE/'source-lock.json'),'retained_partial_batch_result':{'path':str(p.relative_to(REPO)),'sha256':sha(p),'aggregate_passed':False,'reason':'Separate fifth SVD-memory consumer unnecessarily opened absent InnerProductSpace namespace; its independent fresh corrected replay is separate.'},'scoped_kernel_result':r,'scope_of_freshness':'Every closure source compiled from this snapshot into a private empty object root. Four consumers share compiled objects created during this one audit; no pre-existing project objects were used. Only exact pinned external dependency objects were reused.','literal_consumer':{'source':str((BASE/'run-attempt-1/sources'/result['consumer_bindings'][key]['source']).relative_to(REPO)),'sha256':result['consumer_sha256'][result['consumer_bindings'][key]['source']],'bindings':result['consumer_bindings'][key]},'kernel_mode':'LeanCert kernel','allowed_and_observed_axioms':r['observed_axioms'],'ten_exact_clean_pins_before_after':True,'original25_byte_exact_against_2b_before_after':True,'private_or_local_explicit_declarations':[],'generated_or_anonymous_helpers':'All sources are kernel compiled; explicit named declarations are audited individually, and dependency axioms are checked transitively. Anonymous instances and generated constants are not claimed as separate explicit source-name checks.','full_TR04_Target_proved':False,'authoritative_Linux_Comparator':False}
 out=BASE/(key+'-APPROVAL.json');out.write_text(json.dumps(record,indent=2)+'\n');receipts.append({'block':key,'path':str(out.relative_to(REPO)),'sha256':sha(out),'passed':True})
(BASE/'FOUR_BLOCK_ACCEPTANCE.json').write_text(json.dumps({'passed':True,'scope':'Four successful independent block approvals from retained five-block run; fifth diagnostic is not relabeled as a success.','receipts':receipts,'proof_sources_changed':False,'full_TR04_Target_proved':False},indent=2)+'\n')
print(json.dumps(receipts,indent=2))
